function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 10000) return 'The tree has at most 10000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Each node value is a whole number from -100000 to 100000.';
  let open = 1;
  for (const v of root) {
    if (open === 0) return 'Every value after the root needs a parent node.';
    open += v === null ? -1 : 1;
  }
  return null;
}

