function findFrequentTreeSum(root) {
  const counts = new Map();
  let best = 0;
  const subtreeSum = (node) => {
    if (!node) {
      return 0;
    }
    const sum = node.val + subtreeSum(node.left) + subtreeSum(node.right);
    const seen = (counts.get(sum) ?? 0) + 1;
    counts.set(sum, seen);
    best = Math.max(best, seen);
    return sum;
  };
  subtreeSum(root);
  const result = [];
  for (const [sum, count] of counts) {
    if (count === best) {
      result.push(sum);
    }
  }
  return result;
}

