function findFrequentTreeSum(root) {
  // Collect every node, then add up each node's subtree from scratch.
  const all = [];
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!node) continue;
    all.push(node);
    stack.push(node.left, node.right);
  }
  const total = (node) => node ? node.val + total(node.left) + total(node.right) : 0;
  const sums = all.map(total);
  const tally = new Map();
  for (const s of sums) tally.set(s, (tally.get(s) || 0) + 1);
  const top = Math.max(...tally.values());
  return [...tally.keys()].filter(key => tally.get(key) === top);
}

